def unpack_payload():
    data = base64.b64decode(PAYLOAD, validate=True)
    if hashlib.sha256(data).hexdigest() != ARCHIVE_SHA256:
        raise ValueError("The embedded archive checksum failed. Copy the entire setup file again.")
    archive = zipfile.ZipFile(io.BytesIO(data))
    if archive.testzip() is not None:
        raise ValueError("The embedded archive is damaged.")
    for entry in archive.infolist():
        path = PurePosixPath(entry.filename)
        if path.is_absolute() or ".." in path.parts or ".git" in path.parts or "\\" in entry.filename:
            raise ValueError("Unsafe archive path.")
    return archive


def main():
    parser = argparse.ArgumentParser(description="Install the upgraded, standalone PixelForge workspace.")
    parser.add_argument("--output", default="PixelForge-Studio", help="New relative directory to create (must not exist)")
    parser.add_argument("--serve", action="store_true", help="Start a local server and open the browser after installation")
    parser.add_argument("--port", type=int, default=8000, help="Local server port; keep the same port for saved projects")
    parser.add_argument("--verify-only", action="store_true", help="Verify embedded files without writing them")
    args = parser.parse_args()
    if not 1024 <= args.port <= 65535:
        parser.error("Use a port between 1024 and 65535.")
    destination = Path(args.output)
    if destination.is_absolute() or ".." in destination.parts:
        parser.error("Choose a relative output folder without '..'.")
    with unpack_payload() as archive:
        if args.verify_only:
            print(f"Verified {len(archive.infolist())} files. SHA-256: {ARCHIVE_SHA256}")
            return
        if destination.exists() or destination.is_symlink():
            parser.error(f"{destination} already exists. Nothing was overwritten. Choose a different --output folder.")
        destination.mkdir(parents=True, exist_ok=False)
        for entry in archive.infolist():
            target = destination.joinpath(*PurePosixPath(entry.filename).parts)
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(archive.read(entry))
    print(f"Installed PixelForge into {destination}")
    print("47 assets | 990 states | 6,106 frames | 3 standalone pages")
    print("Read README.md, AGENT-API.md, and VALIDATION.md in that folder.")
    print("Browser layout and native storage still need local verification.")
    if not args.serve:
        print(f"Next: cd {destination}")
        print(f"Then: python -m http.server {args.port} --bind 127.0.0.1")
        print(f"Open http://127.0.0.1:{args.port}/index.html")
        return
    handler = functools.partial(http.server.SimpleHTTPRequestHandler, directory=str(destination))
    try:
        server = http.server.ThreadingHTTPServer(("127.0.0.1", args.port), handler)
    except OSError as error:
        print(f"Installation succeeded, but the server could not start: {error}")
        print(f"Run a local server from {destination} using a free port.")
        return
    address = f"http://127.0.0.1:{args.port}/index.html"
    print(f"Serving {address} — press Ctrl+C to stop.")
    print("Keep this host and port to find the same browser-stored projects next time.")
    opener = threading.Timer(0.4, lambda: webbrowser.open(address))
    opener.daemon = True
    opener.start()
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        print("\nServer stopped. Your project data remains in your browser.")
    finally:
        server.server_close()


if __name__ == "__main__":
    main()